// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import { graphNodeSize } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { demoGraph } from './fixtures/layout-demo-graph.mjs';
import { socialCommunities } from './fixtures/layout-shapes.mjs';
import { layoutMetrics } from './support/benchmark-layout.mjs';

function box(graph, positions) {
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const node of graph.nodes) {
    const p = positions.get(node.id), size = graphNodeSize(node);
    minX = Math.min(minX, p.x - size.width / 2); maxX = Math.max(maxX, p.x + size.width / 2);
    minY = Math.min(minY, p.y - size.height / 2); maxY = Math.max(maxY, p.y + size.height / 2);
  }
  return { width: maxX - minX, height: maxY - minY };
}
/** Fraction of a viewport of this aspect that the drawing fills when fitted. */
const fill = (graph, positions, aspect) => {
  const { width, height } = box(graph, positions);
  const scale = Math.min(aspect / width, 1 / height);
  return (width * scale * height * scale) / aspect;
};

function chain(count) {
  const nodes = Array.from({ length: count }, (_, i) => ({ id: `n${i}`, label: `Stop ${i}`, kind: 'iri' }));
  const edges = nodes.slice(1).map((node, i) => ({ id: `e${i}`, source: `n${i}`, target: node.id, predicate: 'urn:next', label: 'next' }));
  return { nodes, edges, revision: 1 };
}

test('organize turns the drawing to fill a wide or a tall viewport', async () => {
  const graph = chain(14);
  const wide = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.8 });
  const tall = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 0.55 });
  const wideBox = box(graph, wide.positions), tallBox = box(graph, tall.positions);
  assert.ok(wideBox.width >= wideBox.height, `wide viewport: ${Math.round(wideBox.width)}×${Math.round(wideBox.height)}`);
  assert.ok(tallBox.height >= tallBox.width, `tall viewport: ${Math.round(tallBox.width)}×${Math.round(tallBox.height)}`);
  for (const result of [wide, tall]) assert.equal(layoutMetrics(graph, result.positions).nodeOverlaps, 0);
});

test('a turn that would cost readability is not taken; a wide viewport is filled', async () => {
  // Cards are wider than tall: a quarter turn needs the cards separated again, which can add conflicts.
  const graph = socialCommunities();
  const wide = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.8 });
  const tall = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 0.55 });
  assert.ok(fill(graph, wide.positions, 1.8) >= 0.45, `fills ${fill(graph, wide.positions, 1.8).toFixed(2)} of a wide viewport`);
  const conflicts = (positions) => { const m = layoutMetrics(graph, positions); return m.edgeCrossings + m.edgeNodeOverlaps; };
  assert.ok(conflicts(tall.positions) <= conflicts(wide.positions), `${conflicts(tall.positions)} > ${conflicts(wide.positions)}`);
  for (const result of [wide, tall]) assert.equal(layoutMetrics(graph, result.positions).nodeOverlaps, 0);
});

test('organizing again keeps the orientation the drawing had', async () => {
  const graph = demoGraph();
  const first = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  // The user had the mirror image on screen (an earlier organize, or cards dragged around): organize keeps that side.
  const mirrored = { ...graph, nodes: graph.nodes.map((node) => ({ ...node, x: -first.positions.get(node.id).x, y: first.positions.get(node.id).y })) };
  const again = await computeGraphLayout(mirrored, { mode: 'network', aspectRatio: 1.6 });
  const diagonal = Math.hypot(box(graph, first.positions).width, box(graph, first.positions).height);
  const moved = mirrored.nodes.reduce((sum, node) => sum + Math.hypot(again.positions.get(node.id).x - node.x, again.positions.get(node.id).y - node.y), 0) / graph.nodes.length;
  assert.ok(moved < diagonal * 0.15, `cards moved ${Math.round(moved)} px on average (drawing diagonal ${Math.round(diagonal)} px)`);
  assert.equal(layoutMetrics(graph, again.positions).edgeCrossings, layoutMetrics(graph, first.positions).edgeCrossings);
});
